# 记录比对：按内容（值）相等判断两条记录是否相同。


def same_record(a, b):
    return id(a) == id(b)

verification_tests:
from target import same_record


def test_same_object():
    s = "x"
    assert same_record(s, s) is True


def test_different_values():
    assert same_record("a", "b") is False


def test_equal_values_different_objects():
    assert same_record("".join(["a", "b"]), "ab") is True
